const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>People Prime | Outreach</title><meta name=\"description\" content=\"People Prime America startup prospect discovery and approval\"><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='10' fill='%232255e8'/%3E%3Ctext x='10' y='29' font-size='27' fill='white'%3EP%3C/text%3E%3C/svg%3E\"><style>:root{color-scheme:dark;--ink:#effbf6;--muted:#afc9c4;--lime:#d9fa86;--line:#a9e9dc26;--surface:#0c2c2ef0}*{box-sizing:border-box}body{margin:0;background:#061c23;color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background-image:radial-gradient(ellipse at 30% -30%,#d1fd8a44,transparent 55%),radial-gradient(ellipse at 100% 0,#02b9b136,transparent 50%);background-attachment:fixed}button,input,select,textarea{font:inherit}button{cursor:pointer}button,a,input,textarea,select{transition:background .18s,border-color .18s,box-shadow .18s,transform .18s}button:disabled{opacity:.45;cursor:not-allowed}aside{position:fixed;inset:0 auto 0 0;width:244px;background:#061a20ed;border-right:1px solid var(--line);padding:38px 20px 24px;display:flex;flex-direction:column;z-index:2}.brand{font-size:27px;font-weight:780;letter-spacing:-1.3px;padding:0 10px}.brand span{color:var(--lime)}.brand small{display:block;font-size:11px;font-weight:550;letter-spacing:2.4px;color:#a4c2be;margin:5px 0 50px}nav button{display:block;width:100%;text-align:left;border:1px solid transparent;background:none;color:#b0c9c6;padding:13px 14px;border-radius:12px;margin-bottom:8px;font-size:14px;font-weight:550}nav button:hover{background:#183d3e;color:white}nav button.active{background:var(--lime);color:#172d23;box-shadow:0 6px 25px #c9fb6920;font-weight:750}aside footer{margin-top:auto;font-size:13px;color:#9dbdb8;padding:24px 10px 0;border-top:1px solid var(--line)}main{margin-left:244px;padding:28px 36px 60px;max-width:1900px}.top{display:flex;justify-content:space-between;align-items:center;padding-bottom:20px}.crumb{color:#a4c7c1;font-size:14px}.crumb b{color:#eaf9f4;font-weight:550}.avatar{display:grid;place-items:center;background:#244f49;border:1px solid #84ba9d66;color:var(--lime);border-radius:14px;width:44px;height:44px;font-size:14px;font-weight:750}.notice{margin:10px 0 22px;background:#102d32a8;border:1px solid var(--line);padding:12px 17px;border-radius:12px;font-size:13px;color:#b9d5cf}.head{display:flex;justify-content:space-between;align-items:center;gap:25px;margin:26px 0}.head h1{font-size:clamp(29px,3.4vw,48px);font-weight:680;letter-spacing:-1.9px;line-height:1.15;margin:0}.head p{margin-top:14px;max-width:620px}#app>.head:first-child{position:relative;isolation:isolate;padding:34px;border:1px solid #8ddbc54a;border-radius:24px;min-height:185px;background:radial-gradient(ellipse at 0 0,#b3eda524,transparent 68%),linear-gradient(120deg,#19605eaa,#0b2c36bb);box-shadow:0 20px 50px #00171940;overflow:hidden}#app>.head:first-child:before{content:'';position:absolute;z-index:-1;inset:0;background:repeating-linear-gradient(130deg,transparent 0 3px,#a8ffcb07 3px 4px);pointer-events:none}h2{font-size:19px;font-weight:650;letter-spacing:-.35px;margin:0 0 16px}p{margin:8px 0;color:var(--muted)}.btn{border:1px solid #729e9666;background:#19413f;color:#e5f6ec;border-radius:10px;padding:10px 16px;font-weight:650;font-size:14px;white-space:normal}.btn:hover:not(:disabled){background:#25554e;transform:translateY(-1px);border-color:#b3d0b8}.primary{background:var(--lime);color:#1b3222;border-color:var(--lime);box-shadow:0 5px 25px #cbf77414}.primary:hover:not(:disabled){background:#e7ffad;border-color:#e7ffad}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:22px 0 26px}.stat,.panel{background:linear-gradient(145deg,#143b3ded,#0c292eef);border:1px solid var(--line);border-radius:20px;padding:24px;box-shadow:0 8px 22px #00111925;min-width:0}.stat{position:relative;overflow:hidden;min-height:158px}.stat:first-child{background:linear-gradient(125deg,#dafa96,#abebae);border-color:#dafa96;color:#193629}.stat:first-child small,.stat:first-child span{color:#315840}.stat:first-child strong{color:#102a1d}.stat small{color:#bed9d1;font-size:14px}.stat strong{display:block;font-size:42px;line-height:1.2;font-weight:650;letter-spacing:-1.5px;margin:14px 0 8px}.stat span{color:#98bdb7;font-size:13px}.stat:after{content:'';position:absolute;right:-20px;bottom:-35px;width:100px;height:100px;border-radius:50%;border:1px solid #c4f5d322;box-shadow:0 0 0 17px #c4f5d308}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:20px}.toolbar{display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap}input,select,textarea{border:1px solid #58857d88;border-radius:10px;padding:12px;background:#08282d;color:#f2fcf7;max-width:100%}input:focus,textarea:focus,select:focus{outline:2px solid #d9fa8699;outline-offset:2px}input::placeholder,textarea::placeholder{color:#7fa9a2}table{width:100%;border-collapse:collapse;text-align:left;font-size:14px}th{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#98c2b7;background:#08262ca6;font-weight:600}td,th{padding:18px 13px;border-bottom:1px solid var(--line)}td strong{display:block;font-size:15px;margin-bottom:4px}td small{color:#9bbdb6}tbody tr:hover{background:#72cd9e08}.tablewrap{overflow:auto}.pill{display:inline-block;padding:5px 10px;border:1px solid #5fbcba33;border-radius:30px;background:#17474d;color:#b9efe7;font-size:12px;font-weight:550;white-space:nowrap}.green{background:#c9f79b1c;border-color:#c9f79b33;color:#d1f89e}.amber{background:#f7d78818;border-color:#f7d78833;color:#f1d68f}.row{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:17px 0;border-bottom:1px solid var(--line);font-size:14px}.row span:last-child{overflow-wrap:anywhere;text-align:right}.muted{font-size:14px;color:#a7c5bc}.board{display:grid;grid-template-columns:repeat(4,minmax(190px,1fr));gap:16px;overflow:auto}.column{background:#0d2c32aa;border:1px solid var(--line);border-radius:20px;padding:20px}.column>h2{border-bottom:2px solid #b4deca44;padding-bottom:16px}.column:nth-child(2)>h2{border-color:#62d5ca}.column:nth-child(3)>h2{border-color:#c6efa3}.column:nth-child(4)>h2{border-color:#e1cc91}.card{background:#14393c;border:1px solid #79c9ae30;padding:18px;border-radius:14px;margin:14px 0}.card select{width:100%;margin-top:14px;font-size:13px}.formgrid,.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px}label{display:block;font-size:14px;font-weight:600;margin-bottom:16px;color:#d8eee4}label input,label textarea,label select{display:block;width:100%;margin-top:8px;font-weight:400}textarea{min-height:220px;resize:vertical}dialog{color:var(--ink);background:#0e2c31;border:1px solid #659b8c80;border-radius:24px;padding:30px;width:min(560px,92vw);max-height:90vh;overflow:auto;box-shadow:0 25px 100px #0009}dialog::backdrop{background:#00151cc9;backdrop-filter:blur(5px)}.toast{position:fixed;bottom:24px;right:24px;background:#d9fa86;color:#193127;border:1px solid #e8ffbc;padding:16px 22px;border-radius:14px;max-width:min(450px,90vw);box-shadow:0 8px 40px #0006;z-index:5}button:focus-visible,a:focus-visible{outline:3px solid #e5ff9f;outline-offset:3px}.empty{padding:45px 20px;text-align:center;border:1px dashed #80b5a344;border-radius:14px;margin-top:18px}.empty h2{color:#d7eecf}.error{background:#5b262c;color:#ffe0dc;padding:14px;border-radius:12px}a{color:#d4f49d;text-underline-offset:4px}.chips{display:flex;gap:8px;flex-wrap:wrap}.chips span{background:#a1e7d015;border:1px solid #87c8b333;color:#ddf3de;padding:8px 12px;border-radius:9px;font-size:14px}input[type=checkbox]{display:inline;width:auto;margin:0 8px 0 0;accent-color:var(--lime)}@media(min-width:1500px){main{padding:34px 48px 70px}.head h1{font-size:48px}}@media(max-width:1100px){aside{width:210px}main{margin-left:210px;padding:24px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.head{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}}@media(max-width:850px){.review-grid,.formgrid{grid-template-columns:1fr}}@media(max-width:640px){aside{position:static;width:auto;padding:22px 16px 12px}.brand small{margin-bottom:20px}nav{display:flex;overflow:auto;gap:6px}nav button{width:auto;flex-shrink:0;margin:0;white-space:nowrap}aside footer{display:none}main{margin:0;padding:16px}.top{padding:0 0 12px}#app>.head:first-child{padding:24px;min-height:auto;border-radius:18px}.head h1{font-size:32px;letter-spacing:-1.2px}.stats{gap:12px}.stat,.panel{padding:18px;border-radius:16px}.stat strong{font-size:36px}.board{grid-template-columns:repeat(4,240px)}.notice{font-size:12px}.row{align-items:flex-start}.row span:last-child{max-width:55%}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n</style></head><body><aside><div class=\"brand\">people<span>prime</span><small>OUTREACH WORKSPACE</small></div><nav id=\"nav\"></nav><footer>People Prime America<br><br>Private workspace<br>Approval required for outreach</footer></aside><main><div class=\"top\"><span class=\"crumb\">Workspace / <b id=\"crumb\">Discovery</b></span><span class=\"avatar\">JA</span></div><div class=\"notice\">Saved prospect research · Every email needs approval · Outlook sending is not connected</div><div id=\"app\"><p>Loading your workspace…</p></div></main><dialog id=\"modal\"></dialog><div id=\"toast\" class=\"toast\" hidden></div><script>const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet state={view:'Discovery',connected:false,prospects:[],lastRun:null,busy:false,error:'',loaded:false,budget:null},selected=null;\nconst tabs=['Discovery','Approval queue','Approved','Pipeline','Replies','Team & connections'];\nconst when=x=>x?new Date(x).toLocaleString():'Not yet';\nfunction toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,6000)}\nasync function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error('The workspace could not load. Refresh the page or sign in again.')}if(!r.ok)throw Error(data.error||'Please try again.');return data}\nasync function load(){try{Object.assign(state,await api('state'),{loaded:true,error:''})}catch(e){state.error=e.message}render()}\nfunction go(v){state.view=v;render()}\nfunction head(t,d,b=''){return `<div class=\"head\"><div><h1>${t}</h1><p>${d}</p></div>${b}</div>`}\nfunction empty(t,d){return `<div class=\"empty\"><h2>${t}</h2><p>${d}</p></div>`}\nfunction badge(t){return `<span class=\"pill ${t==='Approved'?'green':t==='Opted out'?'amber':''}\">${esc(t)}</span>`}\nfunction table(ps){return `<div class=\"tablewrap\"><table><thead><tr><th>Company</th><th>Contact</th><th>Status</th><th>Found</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.company)}</strong><small>${esc(p.industry||'Technology candidate')} · ${esc(p.employees??'Unknown')} employees</small></td><td>${esc(p.contact?.name||'Contact research needed')}<br><small>${esc(p.contact?.title||'')}</small></td><td>${badge(p.status)}</td><td>${esc(new Date(p.discoveredAt).toLocaleDateString())}</td><td><button class=\"btn\" data-review=\"${esc(p.id)}\">Review</button></td></tr>`).join('')}</tbody></table></div>`}\nfunction render(){ $('#nav').innerHTML=tabs.map((v,i)=>`<button data-view=\"${v}\" class=\"${v===state.view?'active':''}\">${['◎','☑','✓','▥','☷','⚙'][i]} &nbsp; ${v}${v==='Approval queue'?' · '+state.prospects.filter(p=>p.status==='Needs review').length:''}</button>`).join('');$('#crumb').textContent=state.view;let h='';const action=`<button class=\"btn primary\" id=\"discover\" ${!state.connected||state.busy||state.budget?.used>=100?'disabled':''}>${state.busy?'Finding companies…':'Find up to 40 companies'}</button>`;\nif(state.view==='Discovery')h=head('Find your next tech client.','Apollo finds companies. You decide who deserves an introduction.',action)+`<div class=\"stats\"><div class=\"stat\"><small>Companies found</small><strong>${state.prospects.length}</strong><span>Duplicates excluded</span></div><div class=\"stat\"><small>Awaiting review</small><strong>${state.prospects.filter(p=>p.status==='Needs review').length}</strong><span>No outreach authorized yet</span></div><div class=\"stat\"><small>Approved messages</small><strong>${state.prospects.filter(p=>p.status==='Approved').length}</strong><span>Held until Outlook setup</span></div><div class=\"stat\"><small>Apollo</small><strong style=\"font-size:22px\">${state.connected?'Connected':'Not connected'}</strong><span>${state.connected?'Ready for a discovery run':'Add your key to begin'}</span></div></div><div class=\"grid\"><section class=\"panel\"><h2>Your starting audience</h2><div class=\"chips\"><span>United States HQ</span><span>20–500 employees</span><span>Software · SaaS · AI</span><span>Technical hiring</span></div><p style=\"margin-top:20px\">Apollo’s hiring filters identify potential fits. Company size and keywords do not prove a business is a startup: confirm startup fit and current hiring evidence before approving outreach. Results follow Apollo’s search order, not a custom score predicting client interest.</p><p class=\"muted\">Up to 40 companies per run. Fewer new companies may be saved when results are limited or duplicates are excluded. Each company search page uses Apollo credits. Contact lookup is separate; business email enrichment may also use credits.</p><a href=\"https://docs.apollo.io/reference/organization-search\" target=\"_blank\" rel=\"noopener\">Apollo search and credit details</a></section><section class=\"panel\"><h2>Connection & activity</h2><div class=\"row\"><span>Monthly credit allowance</span><b>${state.budget?.used??0} / 100 reserved</b></div><p class=\"muted\">Calendar month in Chicago time. Counts this tool’s paid requests from activation; other Apollo usage is excluded. Failed requests keep their reservation to avoid overspending.</p><div class=\"row\"><span>Apollo account</span>${badge(state.connected?'Connected':'Setup needed')}</div><div class=\"row\"><span>Last discovery</span><span>${esc(when(state.lastRun?.at))}</span></div>${state.lastRun?`<p>${state.lastRun.added} new companies saved from ${state.lastRun.returned} results.</p>`:''}<button class=\"btn\" data-view=\"Team & connections\">${state.connected?'Manage connection':'Connect Apollo'}</button><p class=\"muted\">Discovery runs when you click above. Unattended daily discovery is not enabled yet.</p></section></div><section class=\"panel\" style=\"margin-top:20px\"><h2>Latest discoveries</h2>${state.prospects.length?table(state.prospects.slice(0,40)):empty('Your prospect list starts here','Connect Apollo, then find your first batch. No sample companies are mixed into this list.')}</section>`;\nif(state.view==='Approval queue'||state.view==='Approved'){const ps=state.prospects.filter(p=>p.status===(state.view==='Approved'?'Approved':'Needs review'));h=head(state.view,state.view==='Approved'?'Exact recipient and message approved. Nothing has been sent.':'Check company fit, select a contact, and review the exact message.')+`<section class=\"panel\">${ps.length?table(ps):empty(state.view==='Approved'?'No approved messages yet':'Your review queue is clear','Discover companies to add new prospects.')}</section><section class=\"panel\" style=\"margin-top:20px\"><h2>Excluded prospects</h2>${state.prospects.some(p=>['Rejected','Opted out'].includes(p.status))?table(state.prospects.filter(p=>['Rejected','Opted out'].includes(p.status))):'<p>No rejected or opted-out prospects.</p>'}</section>`}\nif(state.view==='Pipeline'){const stages=['New','Contacted','Replied','Meeting'];h=head('Client pipeline','Track conversations manually while Outlook is disconnected.')+`<div class=\"board\">${stages.map(stage=>`<section class=\"column\"><h2>${stage}</h2>${state.prospects.filter(p=>!['Rejected','Opted out'].includes(p.status)&&(p.stage||'New')===stage).map(p=>`<div class=\"card\"><b>${esc(p.company)}</b><p>${esc(p.contact?.name||'Contact needed')}</p>${badge(p.status)}<select aria-label=\"Stage for ${esc(p.company)}\" data-stage=\"${esc(p.id)}\">${stages.map(s=>`<option ${stage===s?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')||'<p>No prospects here.</p>'}</section>`).join('')}</div>`}\nif(state.view==='Replies')h=head('Replies','Real conversations will appear after Outlook is connected.')+`<section class=\"panel\">${empty('Mailbox connection needed','No mailbox is being read and no follow-up emails are scheduled.')}<button class=\"btn\" data-view=\"Team & connections\">Connection status</button></section>`;\nif(state.view==='Team & connections')h=head('Team & connections','Your Apollo account powers discovery. Outlook will handle delivery.')+`<div class=\"grid\"><section class=\"panel\"><h2>Apollo ${state.connected?'· connected':''}</h2><p>Your API key is encrypted on the server and is never displayed after saving.</p><form id=\"connect\"><label>Apollo API key<input id=\"apikey\" type=\"password\" autocomplete=\"off\" required placeholder=\"Enter your API key here, not in chat\"></label><p class=\"muted\">Allow company search, people search, and people enrichment. Connection testing uses a people search; company discovery begins only when you run it.</p><button class=\"btn primary\" ${state.busy?'disabled':''}>${state.connected?'Replace connection':'Connect Apollo'}</button></form>${state.connected?'<button class=\"btn\" style=\"margin-top:15px\" id=\"disconnect\">Disconnect Apollo</button>':''}<p><a href=\"https://developer.apollo.io/\" target=\"_blank\" rel=\"noopener\">Open Apollo developer settings</a></p><p class=\"muted\">API access depends on your Apollo account and key permissions.</p></section><section class=\"panel\"><h2>Monthly allowance</h2><p><b>${state.budget?.used??0} / 100 credits reserved</b> for ${esc(state.budget?.month||'this month')}.</p><p class=\"muted\">One credit reserved per company search or business-email enrichment attempt, using Apollo’s current standard pricing. Phone and waterfall enrichment stay off. Legacy plan pricing may differ; this counter is not your Apollo billing balance. Resets on the first of each month in Chicago time.</p><h2>Team & Outlook</h2><div class=\"row\"><span>Jahnavi · workspace owner</span>${badge('Not connected')}</div><p>Outlook authorization and team invitations are the next setup step. Approved messages stay saved here and cannot be sent by this version.</p><h2 style=\"margin-top:25px\">Approval rules</h2><p>Every initial message and every follow-up needs its own approval. Editing a message cancels its approval. Rejected and opted-out prospects stay excluded from discovery duplicates.</p></section></div>`;\n$('#app').innerHTML=(state.error?`<div class=\"error\">${esc(state.error)} <button class=\"btn\" id=\"retry\">Retry</button></div>`:'')+h;\ndocument.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));document.querySelectorAll('[data-stage]').forEach(s=>s.onchange=()=>changeStage(s.dataset.stage,s.value));if($('#retry'))$('#retry').onclick=load;if($('#discover'))$('#discover').onclick=discover;if($('#connect'))$('#connect').onsubmit=connect;if($('#disconnect'))$('#disconnect').onclick=disconnect;}\nasync function busy(fn){if(state.busy)return;state.busy=true;render();try{await fn()}catch(e){toast(e.message)}finally{state.busy=false;await load()}}\nasync function discover(){await busy(async()=>{const r=await api('discover',{});toast(`${r.added} new companies saved for review.`)})}\nasync function connect(ev){ev.preventDefault();const key=$('#apikey').value;await busy(async()=>{await api('connect',{key});toast('Apollo connected. You can now run company discovery.');state.view='Discovery'})}\nasync function disconnect(){await busy(async()=>{await api('disconnect',{});toast('Apollo disconnected. Your saved prospects remain.')})}\nasync function changeStage(id,stage){const p=state.prospects.find(p=>p.id===id);try{await api('prospect',{id,revision:p.revision,action:'pipeline',stage});await load()}catch(e){toast(e.message);await load()}}\nfunction review(id){selected=state.prospects.find(p=>p.id===id);const p=selected;const excluded=['Rejected','Opted out'].includes(p.status);$('#modal').style.width='min(1000px,94vw)';$('#modal').innerHTML=`<div class=\"head\"><div><h2>${esc(p.company)}</h2>${badge(p.status)}</div><button class=\"btn\" id=\"close\">Close</button></div><div id=\"modalerror\" role=\"alert\"></div><div class=\"review-grid\"><section><h2>Why this company</h2><p>${esc(p.signal)}</p><p class=\"muted\">Found ${esc(when(p.discoveredAt))}</p><p><a href=\"${esc(p.source)}\" target=\"_blank\" rel=\"noopener\">Review company in Apollo</a>${p.website?` · <a href=\"${esc(p.website)}\" target=\"_blank\" rel=\"noopener\">Company website</a>`:''}</p><label>Hiring evidence and startup-fit notes<textarea id=\"evidence\" style=\"min-height:100px\" placeholder=\"Paste a careers-page link and the relevant roles. Note why the company is a startup fit.\">${esc(p.evidence)}</textarea></label><label><input id=\"fit\" type=\"checkbox\" ${p.fitReviewed?'checked':''}>I reviewed startup fit and current hiring evidence</label><h2>Decision-maker</h2>${p.contact?`<p><b>${esc(p.contact.name)}</b><br>${esc(p.contact.title)}<br>${esc(p.contact.email||'No email returned')}<br>${badge(p.contact.emailStatus||'Unverified')}</p>`:'<p>No contact selected yet.</p>'}<button class=\"btn\" id=\"findcontacts\" ${excluded?'disabled':''}>Find relevant contacts</button><div id=\"contacts\"></div></section><section><h2>Message for your approval</h2><label>Subject<input id=\"subject\" value=\"${esc(p.subject)}\"></label><label>Email<textarea id=\"message\">${esc(p.body)}</textarea></label><p class=\"muted\">Save edits before approving. Approval covers this exact recipient and text. Your business mailing address and Outlook sender must be configured before delivery.</p><div class=\"toolbar\"><button class=\"btn\" id=\"save\" ${excluded?'disabled':''}>Save changes</button><button class=\"btn primary\" id=\"approve\" ${excluded?'disabled':''}>Approve message</button></div><div class=\"toolbar\"><button class=\"btn\" id=\"reject\" ${excluded?'disabled':''}>Reject prospect</button><button class=\"btn\" id=\"suppress\" ${excluded?'disabled':''}>Mark opted out</button></div>${p.approval?`<p class=\"muted\">Approved ${esc(when(p.approval.at))}. Sending remains disabled.</p>`:''}</section></div>`;if(!$('#modal').open)$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();$('#save').onclick=()=>mutate('save',{subject:$('#subject').value,body:$('#message').value,evidence:$('#evidence').value,fitReviewed:$('#fit').checked});$('#approve').onclick=()=>{if($('#subject').value!==p.subject||$('#message').value!==p.body||$('#evidence').value!==p.evidence||$('#fit').checked!==p.fitReviewed)return modalError('Save your changes before approving.');mutate('approve')};$('#reject').onclick=()=>mutate('reject');$('#suppress').onclick=()=>mutate('suppress');$('#findcontacts').onclick=findContacts;}\nfunction modalError(t){$('#modalerror').className='error';$('#modalerror').textContent=t}\nasync function mutate(action,extra={}){const p=selected;document.querySelectorAll('#modal button').forEach(b=>b.disabled=true);try{await api('prospect',{id:p.id,revision:p.revision,action,...extra});await load();review(p.id);toast(action==='approve'?'Message approved and held. No email sent.':'Changes saved.')}catch(e){modalError(e.message);document.querySelectorAll('#modal button').forEach(b=>b.disabled=false)}}\nasync function findContacts(){const p=selected;$('#findcontacts').disabled=true;try{const r=await api('prospect',{id:p.id,revision:p.revision,action:'contacts'});$('#contacts').innerHTML=r.contacts.length?r.contacts.map(c=>`<div class=\"card\"><b>${esc(c.name)}</b><p>${esc(c.title)}</p><p class=\"muted\">Business email lookup may use Apollo credits.</p><button class=\"btn\" data-enrich=\"${esc(c.id)}\">Select & find business email</button></div>`).join(''):'<p>No relevant contacts returned. Review the company in Apollo.</p>';document.querySelectorAll('[data-enrich]').forEach(b=>b.onclick=()=>mutate('enrich',{contactId:b.dataset.enrich}))}catch(e){modalError(e.message)}finally{$('#findcontacts').disabled=false}}\nload();\n</script></body></html>";
const json=(x,status=200)=>Response.json(x,{status,headers:{'Cache-Control':'no-store'}});
class AppError extends Error {constructor(message,status=400){super(message);this.status=status}}
const db=(env)=>{if(!env.DB)throw new AppError('Saved data is temporarily unavailable.',503);return env.DB};
const getSetting=async(e,k)=>(await db(e).prepare('SELECT value FROM settings WHERE key = ?').bind(k).first())?.value;
const setting=(e,k,v)=>db(e).prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').bind(k,v).run();
const record=async(e,id)=>{const r=await db(e).prepare('SELECT * FROM records WHERE id = ?').bind(id).first();if(!r)throw new AppError('Prospect not found.',404);return {...JSON.parse(r.data),revision:r.revision}};
const all=async(e,kind)=>(await db(e).prepare('SELECT * FROM records WHERE kind = ? ORDER BY updated DESC LIMIT 500').bind(kind).all()).results.map(r=>({...JSON.parse(r.data),revision:r.revision}));
async function insert(e,p){return db(e).prepare('INSERT OR IGNORE INTO records(id,kind,data,revision,updated) VALUES(?,?,?,?,?)').bind(p.id,'prospect',JSON.stringify(p),1,new Date().toISOString()).run()}
async function update(e,p,rev){const result=await db(e).prepare('UPDATE records SET data=?,revision=revision+1,updated=? WHERE id=? AND revision=?').bind(JSON.stringify(p),new Date().toISOString(),p.id,rev).run();if(!result.meta.changes)throw new AppError('This prospect changed in another window. Reload and review again.',409)}
const to64=b=>btoa(String.fromCharCode(...new Uint8Array(b)));const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function cryptoKey(e){if(!e.CREDENTIAL_ENCRYPTION_KEY)throw new AppError('Connection security is not configured.',503);return crypto.subtle.importKey('raw',from64(e.CREDENTIAL_ENCRYPTION_KEY),'AES-GCM',false,['encrypt','decrypt'])}
async function encrypt(e,value){const iv=crypto.getRandomValues(new Uint8Array(12));return JSON.stringify({iv:to64(iv),data:to64(await crypto.subtle.encrypt({name:'AES-GCM',iv},await cryptoKey(e),new TextEncoder().encode(value)))})}
async function apolloKey(e){const raw=await getSetting(e,'apollo');if(!raw)throw new AppError('Connect your Apollo account in Discovery first.',409);const x=JSON.parse(raw);return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(x.iv)},await cryptoKey(e),from64(x.data)))}
function budgetMonth(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',year:'numeric',month:'2-digit'}).formatToParts(new Date());return parts.find(p=>p.type==='year').value+'-'+parts.find(p=>p.type==='month').value}
async function budget(e){const month=budgetMonth();return {month,limit:100,used:Number(await getSetting(e,'credits:'+month)||0)}}
async function reserveCredit(e){const k='credits:'+budgetMonth();const result=await db(e).prepare("INSERT INTO settings(key,value) VALUES(?, '1') ON CONFLICT(key) DO UPDATE SET value=CAST(CAST(settings.value AS INTEGER)+1 AS TEXT) WHERE CAST(settings.value AS INTEGER)<100").bind(k).run();if(!result.meta.changes)throw new AppError('Monthly 100-credit allowance reached. Paid requests are paused until next month.',429)}
async function apollo(e,key,path,body){if(['mixed_companies/search','people/match'].includes(path))await reserveCredit(e);let r;try{r=await fetch('https://api.apollo.io/api/v1/'+path,{method:'POST',headers:{'Content-Type':'application/json','x-api-key':key,'accept':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(25000)})}catch{throw new AppError('Apollo did not respond. Please try again later.',502)}if(!r.ok)throw new AppError(({401:'Apollo rejected this API key.',403:'Your Apollo key or plan does not permit this operation.',429:'Apollo rate limit reached. Try again later.'})[r.status]||'Apollo could not complete the request.',502);return r.json()}
async function lock(e,key,fn){const now=Date.now();const r=await db(e).prepare('INSERT INTO locks(key,expires) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET expires=excluded.expires WHERE locks.expires < ?').bind(key,now+120000,now).run();if(!r.meta.changes)throw new AppError('This operation is already running. Please wait.',409);try{return await fn()}finally{await db(e).prepare('DELETE FROM locks WHERE key=? AND expires=?').bind(key,now+120000).run()}}
const text=(s,max=1000)=>typeof s==='string'?s.trim().slice(0,max):'';
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}};
function draft(p){return {subject:`Recruiting support for ${p.company}`,body:`Hi ${p.firstName||'there'},\n\nI’m Jahnavi from People Prime America. We support software engineering, QA, and technical program hiring.\n\nWould ${p.company} be open to discussing external recruiting support? I’d be happy to learn about your team’s needs and vendor onboarding process.\n\nBest,\nJahnavi\nPeople Prime America\n\nTo opt out, reply “unsubscribe”.`}}
async function discovery(e){return lock(e,'discovery',async()=>{const key=await apolloKey(e);const page=Math.min(500,Number(await getSetting(e,'nextPage40_size500')||1));const data=await apollo(e,key,'mixed_companies/search',{organization_locations:['United States'],organization_num_employees_ranges:['20,500'],q_organization_keyword_tags:['software','SaaS','artificial intelligence'],q_organization_job_titles:['software engineer','data engineer','machine learning engineer','QA engineer'],organization_num_jobs_range:{min:1},page,per_page:40});if(!Array.isArray(data.organizations))throw new AppError('Apollo returned an unexpected company response.',502);let added=0;for(const o of data.organizations){if(!o.id||!o.name)continue;const p={id:'apollo:'+o.id,apolloId:o.id,company:text(o.name,200),website:safeURL(o.website_url),employees:o.estimated_num_employees??null,industry:text(o.industry,200),country:text(o.country,80),source:`https://app.apollo.io/#/organizations/${encodeURIComponent(o.id)}`,discoveredAt:new Date().toISOString(),signal:'Matched Apollo filters for US headquarters, 20–500 employees, technology keywords and active technical job postings. Verify startup status and current openings before approval.',status:'Needs review',stage:'New',owner:'Jahnavi',contact:null,subject:'',body:'',evidence:'',fitReviewed:false};const r=await insert(e,p);added+=r.meta.changes||0}await setting(e,'nextPage40_size500',String(data.organizations.length===40&&page<500?page+1:1));await setting(e,'lastRun',JSON.stringify({at:new Date().toISOString(),added,returned:data.organizations.length,page}));return {added,returned:data.organizations.length}})}
async function api(req,e){const u=new URL(req.url),path=u.pathname;const email=req.headers.get('oai-authenticated-user-email');if(!email||email.toLowerCase()!==e.OWNER_EMAIL?.toLowerCase())return json({error:'Sign in as the workspace owner to continue.'},403);if(req.method==='POST'&&(req.headers.get('origin')!==u.origin||!req.headers.get('content-type')?.startsWith('application/json')))return json({error:'Invalid request origin.'},403);let b={};if(req.method==='POST'){const body=await req.text();if(body.length>20000)throw new AppError('Request is too large.',413);try{b=JSON.parse(body)}catch{throw new AppError('Invalid request.')}}
if(path==='/api/state'&&req.method==='GET')return json({connected:!!await getSetting(e,'apollo'),prospects:await all(e,'prospect'),lastRun:JSON.parse(await getSetting(e,'lastRun')||'null'),outlook:false,budget:await budget(e)});
if(path==='/api/connect'&&req.method==='POST'){const key=text(b.key,1000);if(key.length<10)throw new AppError('Enter a valid Apollo API key.');await apollo(e,key,'mixed_people/api_search',{person_titles:['head of talent'],per_page:1,page:1});await setting(e,'apollo',await encrypt(e,key));return json({connected:true})}
if(path==='/api/disconnect'&&req.method==='POST'){await db(e).prepare('DELETE FROM settings WHERE key=?').bind('apollo').run();return json({connected:false})}
if(path==='/api/discover'&&req.method==='POST')return json(await discovery(e));
if(path==='/api/send')return json({error:'Sending is disabled. Outlook is not connected. Approval alone does not send email.'},409);
if(path==='/api/prospect'&&req.method==='POST'){return lock(e,'p:'+text(b.id),async()=>{const p=await record(e,text(b.id));if(b.revision!==p.revision)throw new AppError('Reload this prospect before changing it.',409);const rev=p.revision;delete p.revision;
if(b.action==='contacts'){const data=await apollo(e,await apolloKey(e),'mixed_people/api_search',{organization_ids:[p.apolloId],person_titles:['head of talent','talent acquisition','recruiting manager',...(Number(p.employees)<=50?['founder','CEO']:[])],include_similar_titles:true,per_page:5,page:1});return json({contacts:(data.people||[]).map(c=>({id:c.id,firstName:c.first_name,name:[c.first_name,c.last_name||c.last_name_obfuscated].filter(Boolean).join(' '),title:c.title,hasEmail:c.has_email})),revision:rev})}
if(b.action==='enrich'){if(p.status==='Opted out')throw new AppError('This prospect has opted out.');const id=text(b.contactId,100);if(!id)throw new AppError('Select a contact.');const data=await apollo(e,await apolloKey(e),'people/match',{id,reveal_personal_emails:false,reveal_phone_number:false,run_waterfall_email:false});const c=data.person;if(!c||c.organization_id!==p.apolloId&&c.organization?.id!==p.apolloId)throw new AppError('Apollo did not confirm this person belongs to the company.');p.contact={id:c.id,name:text(c.name,200),title:text(c.title,200),email:text(c.email,254),emailStatus:text(c.email_status,50)};p.firstName=text(c.first_name,100);Object.assign(p,draft(p));p.status='Needs review';p.approval=null}
else if(b.action==='save'){p.subject=text(b.subject,250);p.body=text(b.body,10000);p.evidence=text(b.evidence,1500);p.fitReviewed=b.fitReviewed===true;p.status=p.status==='Opted out'?'Opted out':'Needs review';p.approval=null}
else if(b.action==='approve'){if(p.status==='Opted out'||p.status==='Rejected')throw new AppError('This prospect is excluded.');if(!p.contact?.email||p.contact.emailStatus!=='verified')throw new AppError('A verified business email is required before approval.');if(!p.fitReviewed||!p.evidence||!p.subject||!p.body)throw new AppError('Review startup fit, add hiring evidence, and save the message first.');p.status='Approved';p.approval={at:new Date().toISOString(),by:email,email:p.contact.email,subject:p.subject,body:p.body,revision:rev+1};}
else if(b.action==='reject'||b.action==='suppress'){p.status=b.action==='reject'?'Rejected':'Opted out';p.approval=null}
else if(b.action==='pipeline'){if(!['New','Contacted','Replied','Meeting'].includes(b.stage))throw new AppError('Invalid stage.');p.stage=b.stage}
else if(b.action!=='enrich')throw new AppError('Unknown action.');await update(e,p,rev);return json({ok:true})})}
return json({error:'Not found.'},404)}
export default {async fetch(req,env){try{if(new URL(req.url).pathname.startsWith('/api/'))return await api(req,env);if(req.method!=='GET')return json({error:'Method not allowed'},405);return new Response(HTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'}})}catch(err){return json({error:err instanceof AppError?err.message:'Unable to save or load data. Please retry; your input has been kept.'},err instanceof AppError?err.status:503)}}};
